input.contents:
$data = Get-Content 'g:\1.1-PROJECT-MAIN\nha-trang so sánh nhập học\sql\Sim_student -data theo khóa 20.sql' -Raw | ConvertFrom-Json
Write-Host "records:" $data.Count

$nh = $data | Where-Object { ($_.IsCheckInClass -eq $true) -or ($_.IsReceiveMoney -eq $true) }
Write-Host "NH ThongKeNhapHoc (CheckIn OR ReceiveMoney):" $nh.Count

$onlyCheckIn = $data | Where-Object { ($_.IsCheckInClass -eq $true) -and ($_.IsReceiveMoney -ne $true) }
Write-Host "Only IsCheckInClass (not ReceiveMoney):" $onlyCheckIn.Count

$scid0 = $nh | Where-Object { [int64]$_.StudentCollectionID -eq 0 }
Write-Host "NH with StudentCollectionID=0:" $scid0.Count

$course19 = $nh | Where-Object { $_.CourseID -eq '19' }
Write-Host "NH with student CourseID=19:" $course19.Count

$statLogic = $nh | Where-Object { ($_.IsReceiveMoney -eq $true) -and ([int64]$_.StudentCollectionID -gt 0) }
Write-Host "NH Statistic partial (ReceiveMoney + SCID>0):" $statLogic.Count

input.new_string:
Order By
    cl.SpecialBranchID;

